import React from 'react';
import { useNavigate } from 'react-router-dom';
import { logout } from '../services/api'; // Adjust the path to your actual location
import FranchiseListAdmin from './FranchiseListAdmin';
import { Table, Button, Container, Row, Col } from 'react-bootstrap'; // Assuming you want to use Bootstrap for styling

const AdminDashboard = () => {
  const navigate = useNavigate();

  // Handle logout logic
  const handleLogout = async () => {
    try {
      const message = await logout();
      console.log(message); // Optional: Display the success message

      // Clear the token from localStorage
      localStorage.removeItem('token');

      // Navigate to the login page
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <Container fluid>
      <Row className="mb-4">
        <Col>
          <h1 className="text-center">Welcome to Admin Dashboard</h1>
        </Col>
      </Row>

      <Row className="mb-4">
        <Col>
          <Button variant="primary" onClick={() => navigate('/create-user')} className="mr-2">Create User</Button>
          <Button variant="success" onClick={() => navigate('/exam-data')} className="mr-2">Manage Exam Data</Button>
          <Button variant="danger" onClick={handleLogout}>Logout</Button>
        </Col>
      </Row>

      {/* Franchise List Table */}
      <Row>
        <Col>
          <div className="table-responsive">
            <Table striped bordered hover size="lg" className="mb-4">
              <thead>
                <tr>
                  <th style={{ fontWeight: 'bold' }}>Franchise Name</th>
                  <th style={{ fontWeight: 'bold' }}>Location</th>
                  <th style={{ fontWeight: 'bold' }}>Status</th>
                  <th style={{ fontWeight: 'bold' }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                <FranchiseListAdmin /> {/* Assuming this component provides the list of franchises */}
              </tbody>
            </Table>
          </div>
        </Col>
      </Row>
    </Container>
  );
};

export default AdminDashboard;
